// foreach_macros.rs - Foreach processing system for git repositories
// Generated by step4_bootstrap - Foreach Git Processing

use std::fs;
use anyhow::Result;

pub fn get_all_git_repos() -> Result<Vec<String>> {
    let gitmodules_path = "../../.gitmodules";
    if !std::path::Path::new(gitmodules_path).exists() {
        return Ok(vec!["rust-base64".to_string(), "serde".to_string()]); // fallback
    }
    
    let content = fs::read_to_string(gitmodules_path)?;
    let repos: Vec<String> = content
        .lines()
        .filter(|line| line.contains("path = "))
        .map(|line| {
            line.split("path = ")
                .nth(1)
                .unwrap_or("")
                .trim_matches('"')
                .split('/')
                .last()
                .unwrap_or("unknown")
                .replace('-', "_")
                .to_string()
        })
        .collect();
    
    Ok(repos)
}

#[macro_export]
macro_rules! git_subs {
    () => {{
        get_all_git_repos().unwrap_or_default()
    }};
}

#[macro_export]
macro_rules! extractmods {
    ($git_sub_result:expr) => {{
        let crates = $git_sub_result;
        let mut modules = Vec::new();
        for crate_info in crates {
            modules.extend(crate_info.declarations);
        }
        modules
    }};
}

#[macro_export]
macro_rules! mkmods {
    ($modules:expr) => {{
        let modules = $modules;
        // Reduce output for parallel processing
        if modules.len() > 0 && modules.len() <= 5 {
            println!("🔧 {} mods", modules.len());
        }
        modules
    }};
}

#[macro_export]
macro_rules! foreach {
    ($repo_var:ident, $repos_expr:expr, $action:expr) => {{
        let repos = $repos_expr;
        let mut results = Vec::new();
        
        for $repo_var in repos {
            println!("🔄 Processing repo: {}", $repo_var);
            let result = $action;
            results.push(result);
        }
        
        results
    }};
}
